// A stand-in for the Less compiler (only what this test needs: `@name: value;` and `@name` in values), so the test needs no download.
exports.render = async (code, { filename }) => {
  if (!filename.endsWith('.less')) throw new Error('not a .less file: ' + filename);
  const vars = {};
  const body = code.replace(/^@([\w-]+):\s*([^;]+);\s*$/gm, (_, name, value) => ((vars[name] = value), '')).replace(/@([\w-]+)/g, (_, name) => vars[name]);
  return { css: body.trim() + '\n', imports: [] };
};
